RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  it "refuses unrecorded unlocked links in both seeded companies in one error instead of stopping at the first" do
    recorded = YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)
    # Both seeded companies have unlocked links; a record that lists none leaves every one without a disposition.
    empty_record = recorded.merge("companies" => {})
    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: empty_record)

    # "Cutover proceeds only when the orphan, conflict and unlocked-link lists are empty, or every item has a recorded disposition." Refuse with a per-company list of the items that have none.
    expect { source.export(generation: 7, captured_at: Time.utc(2026, 10, 25, 12)) }
      .to raise_error(described_class::Refused) { |error|
        expect(error).to be_a(Timekeeping::Handoff::Store::Error)
        expect(error.refusals.keys).to contain_exactly(fork_and_leaf.id, copper_kettle.id)
        expect(error.refusals.values).to all(be_an(Array).and(be_present))
      }
  end
end

require "rails_helper"

RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  it "refuses only the company whose record names an invoice number that only the other seeded company has" do
    recorded = YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)
    foreign_number = (Invoice.where(company_id: copper_kettle.id).pluck(:invoice_number) -
      Invoice.where(company_id: fork_and_leaf.id).pluck(:invoice_number)).first
    expect(foreign_number).to be_present

    tampered = Marshal.load(Marshal.dump(recorded))
    tampered.fetch("companies").fetch("Fork & Leaf Salads")[foreign_number] =
      { "entry_ids" => [], "disposition" => Timekeeping::SeedDisposition::RESERVE }
    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: tampered)

    # "Refuse, never guess, when a number is missing, matches no invoice of that company, or would link an entry to another company's invoice."
    expect { source.export(generation: 7, captured_at: Time.utc(2026, 10, 25, 12)) }
      .to raise_error(described_class::Refused) { |error|
        expect(error.refusals.keys).to eq([fork_and_leaf.id])
        expect(error.refusals.fetch(fork_and_leaf.id).join("\n")).to include(foreign_number)
      }
  end
end

require "rails_helper"

RSpec.describe Timekeeping::Handoff::LegacySource, :two_tenant_seed, :seeded_without_transaction do
  it "a retried export of the seed with the same capture time gives identical checkpoint rows and corrections" do
    recorded = YAML.load_file(Timekeeping::SeedDispositionRecorder::DEFAULT_PATH)
    source = described_class.new(connection: ActiveRecord::Base.connection, recorded_disposition: recorded)
    captured_at = Time.utc(2026, 10, 25, 12)

    first = source.export(generation: 7, captured_at:)
    second = source.export(generation: 7, captured_at:)

    # "Make every derived value repeatable: a reservation's `operation_id` is a UUIDv5 of company, entry and invoice, and timestamps are a capture time passed in."
    expect(second[:checkpoint].rows).to eq(first[:checkpoint].rows)
    expect(second[:checkpoint].digest).to eq(first[:checkpoint].digest)
    expect(second[:corrections]).to eq(first[:corrections])
    reservations = first[:checkpoint].rows.fetch("reservations")
    expect(reservations).to be_present
    expect(reservations.pluck("created_at")).to all(eq(captured_at))
    expect(reservations.map { |row| [row["company_id"], row["entry_id"]] }.uniq.size).to eq(reservations.size)
  end
end

